        console.log('[Net] Cleared');
        highlightedNet = null;
        selectedTraceId = null;
        interactionState.selectedTraceId = null;
        labelPosition = null;
        dirty = true;
        e.preventDefault();
        return;
      }
      if (isRouting) {
        cancelRouting();
        return;
      }
