// Complete 555 Timer LED Blink Circuit
// NE555 in astable mode, ~1.4 Hz blink
// Supply: 5V via 2-pin header
version 1

---
version 1

// Simple power indicator circuit
// - 5V power input via 2-pin header
// - LED with current limiting resistor (330R for ~10mA @ 5V)
---
// Najprostszy zasilacz 5V
// Wejście: 7-12V DC
// Wyjście: 5V stabilizowane
version 1

/**
 * Viewport state and coordinate transformations
 * Converts between world coordinates (nanometers, Y-up) and screen coordinates (pixels, Y-down)
 */

export interface Viewport {
  // View center in world coordinates (nanometers)
  centerX: number;
  centerY: number;
  // Pixels per nanometer
  scale: number;
  // Canvas dimensions
  width: number;
  height: number;
}

/**
 * Create a new viewport with default zoom
 * Default scale: 1mm = 100px (reasonable starting zoom)
 * 1mm = 1,000,000 nm, so scale = 100 / 1,000,000 = 0.0001
 */
export function createViewport(width: number, height: number): Viewport {
  return {
    centerX: 0,
    centerY: 0,
    scale: 0.0001,
    width,
    height,
  };
}

