#project-manager {
  position: fixed;
  inset: 0;
  top: 41px; /* below toolbar */
  background: var(--bg-secondary);
  z-index: 150;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow-y: auto;
}
#project-manager.hidden {
  display: none;
}
.pm-container {
  max-width: 720px;
  width: 100%;
  padding: 48px 24px;
}
.pm-header {
  text-align: center;
  margin-bottom: 40px;
}
.pm-header h1 {
  font-size: 28px;
  font-weight: 700;
  color: var(--text-primary);
  margin: 0 0 8px 0;
}
.pm-header p {
  font-size: 14px;
  color: var(--text-secondary);
  margin: 0;
}
.pm-section {
  margin-bottom: 32px;
}
.pm-section h2 {
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--text-tertiary);
  margin: 0 0 12px 0;
}
.pm-templates-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 12px;
}
.pm-template-card {
  background: var(--bg-elevated);
  border: 1px solid var(--border-primary);
  border-radius: 8px;
  padding: 16px;
  cursor: pointer;
  transition: border-color 0.15s, box-shadow 0.15s;
  text-align: center;
}
.pm-template-card:hover {
  border-color: var(--accent-primary);
  box-shadow: 0 2px 8px var(--shadow);
}
.pm-template-icon {
  font-size: 28px;
  margin-bottom: 8px;
}
.pm-template-card h3 {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  margin: 0 0 4px 0;
