.pm-template-card p {
  font-size: 11px;
  color: var(--text-secondary);
  margin: 0;
  line-height: 1.4;
}
/* Recent files */
.pm-recent-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.pm-recent-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 8px 12px;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.1s;
}
.pm-recent-item:hover {
  background: var(--bg-elevated);
}
.pm-recent-thumb {
  border-radius: 4px;
  border: 1px solid var(--border-secondary);
  object-fit: cover;
  flex-shrink: 0;
}
.pm-recent-thumb-placeholder {
  width: 48px;
  height: 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  border-radius: 4px;
  border: 1px solid var(--border-secondary);
  background: var(--bg-elevated);
  flex-shrink: 0;
}
.pm-recent-info {
  flex: 1;
  min-width: 0;
}
.pm-recent-name {
  font-size: 13px;
  font-weight: 500;
  color: var(--text-primary);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.pm-recent-date {
  font-size: 11px;
  color: var(--text-tertiary);
}
.pm-recent-empty {
  font-size: 12px;
  color: var(--text-tertiary);
  padding: 8px 12px;
}
/* Open file button */
#pm-open-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  background: var(--accent-primary);
  color: white;
  border: none;
  padding: 8px 20px;
  border-radius: 6px;
  font-size: 13px;
  font-weight: 500;
  cursor: pointer;
  transition: background-color 0.15s;
}
#pm-open-btn:hover {
  background: var(--accent-hover);
}
.pm-actions {
  text-align: center;
  margin-top: 24px;
}

